// AddedEdges returns all edge names that were set/added in this mutation.
func (m *CycleMutation) AddedEdges() []string {
	edges := make([]string, 0, 3)
	if m.team != nil {
		edges = append(edges, cycle.EdgeTeam)
	}
	if m.issues != nil {
		edges = append(edges, cycle.EdgeIssues)
	}
	if m.documents != nil {
		edges = append(edges, cycle.EdgeDocuments)
	}
	return edges
}

// AddedIDs returns all IDs (to other nodes) that were added for the given edge
// name in this mutation.
func (m *CycleMutation) AddedIDs(name string) []ent.Value {
	switch name {
	case cycle.EdgeTeam:
		if id := m.team; id != nil {
			return []ent.Value{*id}
		}
	case cycle.EdgeIssues:
		ids := make([]ent.Value, 0, len(m.issues))
		for id := range m.issues {
			ids = append(ids, id)
		}
		return ids
	case cycle.EdgeDocuments:
		ids := make([]ent.Value, 0, len(m.documents))
		for id := range m.documents {
			ids = append(ids, id)
		}
		return ids
	}
	return nil
}

